-- RUN 2026-09-23, database 235, SELECT only. L6 A28. Quantify creation/issue/effective date mismatch. Original implicit timezone diagnostic; 2 aggregate rows. Final corrected estimates use explicit America/Chicago.
-- Expected if original definitions agree: zero date mismatches / zero exposure inflation.
SELECT quote_type,count() AS home_rows,countIf(quote_effective_timestamp IS NULL) AS missing_quote_effective,countIf(policy_effective_timestamp IS NULL) AS missing_policy_effective,countIf(toDate(quote_effective_timestamp)!=toDate(quote_issued_timestamp)) AS quote_effective_differs_issue,countIf(toDate(policy_effective_timestamp)!=toDate(quote_effective_timestamp)) AS policy_effective_differs_quote,quantilesExact(0.1,0.5,0.9)(dateDiff('day',toDate(quote_issued_timestamp),toDate(quote_effective_timestamp))) AS effective_minus_issue_days FROM dbt.ipod_standard_mga_raw_policy_info WHERE quote_status='Issued' AND quote_type IN('NewBusiness','Cancellation') AND pol_created_timestamp>=toDateTime('2024-01-01 00:00:00') AND pol_created_timestamp<toDateTime('2026-07-01 00:00:00') GROUP BY quote_type;

